package com.sr.voicechat;
import android.os.Bundle;import android.view.Gravity;import android.widget.Button;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import com.google.firebase.database.DataSnapshot;import com.google.firebase.database.DatabaseError;import com.google.firebase.database.DatabaseReference;import com.google.firebase.database.FirebaseDatabase;import com.google.firebase.database.ValueEventListener;import java.util.HashMap;import java.util.Map;import java.util.Random;
public class GreedyLionActivity extends AppCompatActivity {
private String roomId,roomOwnerId,myId,myName;private long myBalance=0;private int selectedBet=1000;private TextView tvBalance,tvLion,tvResult,tvBetLabel;private Button btnPlay;private Random rnd=new Random();private boolean spinning=false;
private long getLongVal(DataSnapshot s,String k){try{Object v=s.child(k).getValue();if(v==null)return 0;if(v instanceof Number)return ((Number)v).longValue();return Long.parseLong(String.valueOf(v).replace(",","").trim());}catch(Exception e){return 0;}}
private long readWallet(DataSnapshot s){long m=0;m=Math.max(m,getLongVal(s,"coins"));m=Math.max(m,getLongVal(s,"coinBalance"));m=Math.max(m,getLongVal(s,"walletCoins"));m=Math.max(m,getLongVal(s,"sendingCoins"));return m;}
private String formatBet(int v){if(v>=100000)return (v/100000)+" Lakh";if(v>=1000)return (v/1000)+"K";return String.valueOf(v);}
@Override protected void onCreate(Bundle savedInstanceState){super.onCreate(savedInstanceState);android.content.SharedPreferences prefs=getSharedPreferences("SR_USER",MODE_PRIVATE);myId=prefs.getString("PROFILE_ID","");if(myId==null||myId.isEmpty())myId=prefs.getString("MY_9DIGIT_ID","");myName=prefs.getString("USER_NAME","User");roomId=getIntent().getStringExtra("ROOM_ID");roomOwnerId=getIntent().getStringExtra("ROOM_OWNER_ID");if(roomId==null)roomId="";if(roomOwnerId==null)roomOwnerId=roomId;
LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(40,40,40,40);root.setGravity(Gravity.CENTER);root.setBackgroundColor(0xFF1A1333);
TextView title=new TextView(this);title.setText("🦁 Greedy Lion");title.setTextSize(28);title.setTextColor(0xFFFFD700);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setGravity(Gravity.CENTER);root.addView(title);
TextView sub=new TextView(this);sub.setText("Room theke ber na hoye khelun");sub.setTextColor(0xFFAAAAAA);sub.setGravity(Gravity.CENTER);sub.setPadding(0,8,0,20);root.addView(sub);
tvBalance=new TextView(this);tvBalance.setText("💰 Balance: Loading...");tvBalance.setTextSize(18);tvBalance.setTextColor(0xFFFFFFFF);tvBalance.setTypeface(null,android.graphics.Typeface.BOLD);tvBalance.setGravity(Gravity.CENTER);tvBalance.setPadding(0,0,0,20);root.addView(tvBalance);
tvLion=new TextView(this);tvLion.setText("🦁");tvLion.setTextSize(120);tvLion.setGravity(Gravity.CENTER);tvLion.setPadding(0,10,0,10);root.addView(tvLion);
tvResult=new TextView(this);tvResult.setText("Bet select kore PLAY chap dao!");tvResult.setTextSize(16);tvResult.setTextColor(0xFFFFD700);tvResult.setGravity(Gravity.CENTER);tvResult.setPadding(0,10,0,20);root.addView(tvResult);
tvBetLabel=new TextView(this);tvBetLabel.setText("Bet: 1K (1,000) Coins");tvBetLabel.setTextSize(16);tvBetLabel.setTextColor(0xFFFFFFFF);tvBetLabel.setGravity(Gravity.CENTER);tvBetLabel.setPadding(0,0,0,10);root.addView(tvBetLabel);
LinearLayout betRow=new LinearLayout(this);betRow.setOrientation(LinearLayout.HORIZONTAL);betRow.setGravity(Gravity.CENTER);int[] bets={1000,10000,100000,500000};String[] betLabels={"1K","10K","100K","500K"};for(int i=0;i<bets.length;i++){int b=bets[i];Button bb=new Button(this);bb.setText(betLabels[i]);bb.setBackgroundTintList(android.content.res.ColorStateList.valueOf(b==selectedBet?0xFFFF9800:0xFF2A1B4E));bb.setTextColor(0xFFFFFFFF);bb.setOnClickListener(v->{selectedBet=b;tvBetLabel.setText("Bet: "+formatBet(b)+" ("+b+") Coins");for(int j=0;j<betRow.getChildCount();j++){if(betRow.getChildAt(j) instanceof Button)((Button)betRow.getChildAt(j)).setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF2A1B4E));}bb.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFFF9800));});betRow.addView(bb);}root.addView(betRow);
btnPlay=new Button(this);btnPlay.setText("🎮 PLAY - SPIN LION");btnPlay.setTextSize(18);btnPlay.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFFF9800));btnPlay.setTextColor(0xFFFFFFFF);btnPlay.setPadding(0,20,0,20);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,LinearLayout.LayoutParams.WRAP_CONTENT);lp.topMargin=30;root.addView(btnPlay,lp);
btnPlay.setOnClickListener(v->playGame());
Button btnBack=new Button(this);btnBack.setText("⬅ Back to Room");btnBack.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF444444));btnBack.setTextColor(0xFFFFFFFF);LinearLayout.LayoutParams lp2=new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,LinearLayout.LayoutParams.WRAP_CONTENT);lp2.topMargin=16;root.addView(btnBack,lp2);btnBack.setOnClickListener(v->finish());
setContentView(root);loadWallet();}
private void loadWallet(){if(myId==null||myId.isEmpty())return;DatabaseReference ref=FirebaseDatabase.getInstance().getReference("users").child(myId);ref.addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){myBalance=readWallet(s);tvBalance.setText("💰 Balance: "+myBalance+" Coins");}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void playGame(){if(spinning)return;if(myBalance<selectedBet){Toast.makeText(this,"Not enough Coins! Need "+selectedBet,Toast.LENGTH_SHORT).show();return;}spinning=true;btnPlay.setEnabled(false);tvResult.setText("🦁 Lion ghurche...");String[] lions={"🦁","🐯","🐅","🦁","🐯","🐅","👑","🦁"};new android.os.Handler().postDelayed(new Runnable(){int step=0;@Override public void run(){tvLion.setText(lions[step%lions.length]);step++;if(step<12){new android.os.Handler().postDelayed(this,120);}else{finishSpin();}}},120);}
private void finishSpin(){int winChance=rnd.nextInt(100);boolean win=winChance<45;long winAmount=win?(long)selectedBet*3:0;long newBal;if(win){newBal=myBalance-selectedBet+winAmount;tvLion.setText("🦁👑");tvResult.setText("🎉 YOU WIN! +"+winAmount+" Coins");}else{newBal=myBalance-selectedBet;tvLion.setText("😿");tvResult.setText("😿 Lose! -"+selectedBet+" Coins");}myBalance=newBal;tvBalance.setText("💰 Balance: "+myBalance+" Coins");updateWalletInFirebase(win,winAmount);spinning=false;btnPlay.setEnabled(true);}
private void updateWalletInFirebase(boolean win,long winAmount){if(myId==null||myId.isEmpty())return;DatabaseReference ref=FirebaseDatabase.getInstance().getReference("users").child(myId);Map<String,Object> m=new HashMap<>();m.put("coins",myBalance);m.put("coinBalance",myBalance);m.put("walletCoins",myBalance);m.put("sendingCoins",myBalance);ref.updateChildren(m);if(win&&roomOwnerId!=null&&!roomOwnerId.isEmpty()){try{DatabaseReference rRef=FirebaseDatabase.getInstance().getReference("active_rooms").child(roomOwnerId).child("ranking").child("daily").child(myId);rRef.addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){long prev=getLongVal(s,"coins");Map<String,Object> ru=new HashMap<>();ru.put("coins",prev+winAmount);ru.put("name",myName);rRef.updateChildren(ru);}@Override public void onCancelled(@NonNull DatabaseError e){}});}catch(Exception ignored){}}}
}
